    "title": "にもかかわらず・のに・に加えて",
    "reading": "にもかかわらず・のに・にくわえて",
    "category": "文法辨析",
    "summary": "にもかかわらず＝儘管A卻B，後項違反正常預期；のに較口語；に加えて表示追加，但動詞普通形通常需名詞化後接。",
