    "passage": "関係各位\n\n企画課\n\n展示会準備に関するお知らせ\n\n展示会に関し、前日および当日の担当業務を各々下記の通り決定いたしましたので、お知らせいたします。\n\n記\n\n（1）前日までの会場セッティングについて\n・ブースのセッティングは営業一課が○月○日までに準備する。\n・会場設営は営業一課全員で行う。\n\n（2）当日の配布物について\n・商品説明パンフレットは、企画課が準備する。\n・その他の配布物は、販売課が準備する。\n\n（3）当日のシフトについて\n・会場　商品説明：販売課（4名）、企画課（2名）\n　　　　注文受付：営業一課全員\n・応接室　役員対応：秘書課（1名）、総務課（1名）\n・駐車場　誘導・案内：総務課（1名）、営業二課（1名）\n\n注意：当日の説明マニュアルは、2日前までに営業一課渡辺が準備する。\n\n以上",
