    "passage": "社員各位\n\n総務部長\n\nフレックスタイム制度見直しについて\n\nわが社で行っているフレックスタイム制度について、前回の役員会議で討議しました結果を皆様にお知らせいたします。\nかねてから定時に社員が揃わないことでお客様にご迷惑をかけ、また作業の能率も下げているとの声が各部署よりあがっておりました。\nそのような状況に鑑み、本年度をもって管理職に対する本制度の廃止を決定いたしました。また将来は、一般職についても取りやめる方向で検討中です。\nなお、育児や介護など、特別の理由のある社員にのみ、継続という方向で対応していく所存であります。\n皆様の生活に影響を与えることもあるかとは思いますが、ご理解のほどよろしくお願い申し上げます。",
