    "translation_zh_tw": "【前文】\n社長對新進員工表示：要達成銷售目標有很多方法。向前輩學習銷售訣竅當然重要，在競爭激烈的現在也必須因應狀況調整銷售方式；但比這些更重要、最重要的是「永不放棄」的精神。不要因一點嚴厲忠告就受挫；客戶說「不」才是銷售的開始。一兩次失敗沒什麼，要能冷靜判斷情況並在一次次打擊後爬起來。\n\n【題目】\n社長認為銷售活動中最重要的是什麼？\n\n【選項】\n1. 向前輩學銷售方法\n2. 依情況改變銷售方式\n3. 被打擊就反擊回去的精神力\n4. 即使失敗也能重新來過的精神力",
