    "passage": "新入社員の皆さんへ\n\nみなさん、がんばっていますか。\n\n販売目標を達成するには複数の道があります。\n先輩社員にセールスのコツを教わるのはもちろん大切ですが、\n競争がますます激化している現在、それだけでは不充分です。\n顧客へのアプローチ方法から契約に至るまで、一人一人が状況に応じてセールス方法を工夫しなければ良い結果は得られません。\nしかし、それにも増して何より大切なのは「ネバーギブアップ」の精神です。\nちょっと苦言を呈されただけで、傷ついてへこんでしまうようでは、よいセールスはできません。\nお客さんに「ノー」と言われてセールスは始まるのです。\n「何がなんでも目標を達成するぞ」という強い思いがあれば、\n一つや二つの失敗など、なんのことはありません。\n冷静に状況を判断しつつ、打たれてもたたかれてもはい上がってくる、そんな精神力を持ってほしいと思います。\nそういう人たちの集団こそが、どんな高い目標でもこなせるのです。\n\n皆さん、期待しております。",
