      "③「～に対して」＝對某對象採取行為，或形成對比。例：「顧客に対して説明する」。本題要的是公司立場，不是行為對象。【錯誤類型：GRAMMAR_FUNCTION】",
      "④「～に限って」＝唯獨／偏偏／只限於。例：「忙しい日に限って電話が多い」。本題沒有排他或例外語意。【錯誤類型：GRAMMAR_FUNCTION】"
