      "③「～に伴って」＝伴隨某變化或事件而發生另一變化，前面多接名詞或「Vの」。本題既有接續問題，也不是伴隨關係。【錯誤類型：GRAMMAR_FUNCTION】",
      "④「～にもかかわらず」＝儘管A卻B。遲到後理應道歉，但實際「一言も謝らなかった」，正是違反正常期待的逆接，正解。"
