    "option_details": [
      "①「時間＋をもって」＝以該時間為正式界線／生效點。人事通知「今月末をもって転勤する」是典型商務表現，正解。",
      "②「～や否や」＝一……立刻……，如「12時になるや否や出発した」。本題只在通知調職生效時間，不強調月底一到瞬間立刻發生。【錯誤類型：GRAMMAR_FUNCTION】",
      "③「～に至って」＝到了某階段／發展到某地步，通常有過程推進語感。本題沒有「到這一步才」的發展過程。【錯誤類型：GRAMMAR_FUNCTION】",
      "④「～を限りに」＝以某日／某次為最後，此後停止原有活動。可用於「今月末を限りに東京勤務を終える」，但本題重點是新的人事異動生效，標準表現是「をもって」。【錯誤類型：REGISTER_MISMATCH】"
    ],
