    "type": "keigo",
    "passage": "",
    "assets": [],
    "stem": "大変申し訳ありませんが、担当者がただいま外出しておりまして、詳細については分かり＿＿＿＿。",
    "options": [
      "えます",
      "えません",
      "かねます",
      "かねません"
    ],
    "answer": 2,
    "category": "商務敬語",
    "explanation": "「Vます形＋かねます」＝立場や状況上、難しくてできないことを婉曲に表す。「担当者不在で詳細が分からない」という電話応対では「分かりかねます」が適切。",
    "translation_zh_tw": "非常抱歉，負責人目前外出了，因此關於詳細情況，我現在無法回答／不太清楚。",
