      "②「～とばかりに」＝彷彿在說A似地，用行動表達未明說的話，如「帰れとばかりに時計を見た」。本題需要條件，不是樣態引用。【錯誤類型：GRAMMAR_FUNCTION】",
      "③「～としても」＝即使假定A成立，也B，屬讓步假設。如「業績が上がるとしても、過度な残業は避ける」。本題是因A重要而願意承擔B，不是讓步。【錯誤類型：GRAMMAR_FUNCTION】",
